import React, { useEffect, useState } from "react";
// react-bootstrap components
import { Badge, Button, Navbar, Nav, Container } from "react-bootstrap";

function Maps() {
  const [markers, setMarkers] = useState([]);

  // ดึงพิกัดจาก Database
  useEffect(() => {
    fetch('http://localhost:3000/api/map-data')
      .then(res => res.json())
      .then(data => {
        console.log("Map Data:", data); // ดูข้อมูลใน Console (กด F12)
        setMarkers(data);
      })
      .catch(err => console.error(err));
  }, []);

  // เนื่องจากเราไม่มี Google Maps Component ที่สมบูรณ์ในตัวอย่าง 
  // ผมจะแสดงเป็นรายการพิกัดให้ดูแทน เพื่อยืนยันว่าข้อมูลมาจริง
  return (
    <Container fluid>
      <div className="map-container">
        <h3>📍 Bus Stop Locations (Database Data)</h3>
        <ul>
            {markers.map((stop, index) => (
                <li key={index} style={{marginBottom: '10px'}}>
                    <strong>{stop.Name}</strong> <br/>
                    Lat: {stop.latitude}, Long: {stop.longitude}
                </li>
            ))}
        </ul>
        <p style={{color:'red'}}>
            *หมายเหตุ: เพื่อให้แสดงเป็นแผนที่จริง คุณต้องนำพิกัดเหล่านี้ไปใส่ใน Google Map Component 
            และต้องมี Google Maps API Key ครับ
            <img
              src="/map.png"
              alt="Map"
              style={{ width: "100%", borderRadius: "12px" }}
            />
        </p>
      </div>
    </Container>
  );
}

export default Maps;
